// Petite fonction de masquage : ne garde que les 4 derniers caracteres
function masquer(valeur) {
  if (!valeur) return null
  return '****' + String(valeur).slice(-4)
}

// On construit l'entree de log comme un objet, pas comme une phrase
function journaliserConnexion(req, utilisateur, succes) {
  const entree = {
    horodatage: new Date().toISOString(), // le QUAND, au format standard
    evenement: 'connexion',               // le type d'evenement de securite
    correlationId: req.correlationId,     // identifiant de correlation de la requete
    utilisateurId: utilisateur.id,        // le QUI (un identifiant, pas le nom en clair)
    adresseIp: masquer(req.ip),           // masquee : donnee personnelle
    resultat: succes ? 'succes' : 'echec',
    // JAMAIS de mot de passe ni de jeton ici :
    carte: masquer(utilisateur.numeroCarte) // on ne garde que ****1234
  }
  // console.log emet une ligne JSON, lisible par un collecteur de logs
  console.log(JSON.stringify(entree))
}

// Compteur simple d'echecs d'autorisation (403) par utilisateur et par minute
const compteurs = new Map()
const SEUIL = 20 // au-dela de 20 refus en une minute, on alerte

function surUnRefus403(utilisateurId) {
  const cle = utilisateurId + ':' + minuteCourante()
  const n = (compteurs.get(cle) || 0) + 1
  compteurs.set(cle, n)

  if (n === SEUIL) {
    // On franchit le seuil : on emet une alerte (ici un log structure dedie)
    console.log(JSON.stringify({
      evenement: 'alerte',
      signal: 'pic_403',
      utilisateurId: utilisateurId,
      valeur: n,
      seuil: SEUIL,
      horodatage: new Date().toISOString()
    }))
    // En vrai : notifier l'equipe et demander au rate limiting de freiner l'appelant
  }
}

function minuteCourante() {
  return Math.floor(Date.now() / 60000)
}
